CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','traveller') NOT NULL DEFAULT 'traveller') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE trips(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,route VARCHAR(255) NOT NULL,dates VARCHAR(120) NOT NULL,description TEXT NOT NULL,itinerary TEXT NOT NULL,inclusions TEXT NOT NULL,seats INT UNSIGNED NOT NULL DEFAULT 0,price DECIMAL(10,2) NOT NULL DEFAULT 0,cost DECIMAL(10,2) NOT NULL DEFAULT 0,image VARCHAR(500) NOT NULL DEFAULT '',published BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE enquiries(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,message TEXT NOT NULL,status ENUM('new','contacted','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(trip_id) REFERENCES trips(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE travellers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,trip_id INT NOT NULL,status VARCHAR(80) NOT NULL DEFAULT 'Enquiry',payment VARCHAR(80) NOT NULL DEFAULT 'Not collected',details TEXT NOT NULL,UNIQUE(user_id,trip_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(trip_id) REFERENCES trips(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE attempts(id INT AUTO_INCREMENT PRIMARY KEY,ip VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO trips(title,route,dates,description,itinerary,inclusions,seats) VALUES ('Japan Discovery','Vancouver • Japan • Hong Kong • Vancouver','Spring 2027 — proposed','Cherry blossoms, culture and extraordinary landscapes.','Osaka and Kyoto\nMount Fuji region\nTokyo\nHong Kong stopover','Proposed flights, accommodation and transport; final inclusions pending.',6),('Ultimate Asian Escape','Vancouver • Cebu • Japan • Hong Kong • Vancouver','Spring 2027 — proposed','Tropical islands meet Japan’s iconic landscapes.','Cebu\nOsaka and Kyoto\nMount Fuji\nTokyo\nHong Kong stopover','Proposed flights, accommodation and transport; final inclusions pending.',6);